// Add crew member logic
const operation = $input.first().json;

// Validate input
if (!operation.name || !operation.role || !operation.specialization) {
  return [{
    json: {
      success: false,
      error: "Missing required fields: name, role, specialization"
    }
  }];
}

// Simulate crew addition
const newMember = {
  name: operation.name,
  role: operation.role,
  specialization: operation.specialization,
  llm_preference: operation.llm_preference || "openai/gpt-4o-mini",
  added_at: new Date().toISOString()
};

return [{
  json: {
    success: true,
    operation: "add_crew",
    crew_member: newMember,
    message: `Crew member ${operation.name} added successfully`
  }
}];

// Remove crew member logic
const operation = $input.first().json;

if (!operation.name) {
  return [{
    json: {
      success: false,
      error: "Missing crew member name"
    }
  }];
}

// Simulate crew removal
return [{
  json: {
    success: true,
    operation: "remove_crew",
    crew_member: operation.name,
    message: `Crew member ${operation.name} removed successfully`
  }
}];

// Create mission logic
const operation = $input.first().json;

if (!operation.mission_id || !operation.name || !operation.description) {
  return [{
    json: {
      success: false,
      error: "Missing required fields: mission_id, name, description"
    }
  }];
}

// Simulate mission creation
const newMission = {
  mission_id: operation.mission_id,
  name: operation.name,
  description: operation.description,
  mission_type: operation.mission_type || "project_development",
  required_crew_size: operation.required_crew_size || 3,
  priority: operation.priority || "normal",
  created_at: new Date().toISOString()
};

return [{
  json: {
    success: true,
    operation: "create_mission",
    mission: newMission,
    message: `Mission ${operation.name} created successfully`
  }
}];

// Complete mission logic
const operation = $input.first().json;

if (!operation.mission_id || !operation.outcomes) {
  return [{
    json: {
      success: false,
      error: "Missing required fields: mission_id, outcomes"
    }
  }];
}

// Simulate mission completion
return [{
  json: {
    success: true,
    operation: "complete_mission",
    mission_id: operation.mission_id,
    outcomes: operation.outcomes,
    lessons_learned: operation.lessons_learned || [],
    completed_at: new Date().toISOString(),
    message: `Mission ${operation.mission_id} completed successfully`
  }
}];

// Generate crew report logic
const report = {
  system_status: "operational",
  total_crew_members: 9,
  active_missions: 2,
  completed_missions: 15,
  crew_availability: {
    "Mission Coordinator": {"active_missions": 1, "total_experience": 8},
    "Execution Commander": {"active_missions": 1, "total_experience": 12},
    "Data Analyst": {"active_missions": 0, "total_experience": 10}
  },
  report_generated: new Date().toISOString()
};

return [{
  json: {
    success: true,
    operation: "crew_report",
    report: report,
    message: "Crew report generated successfully"
  }
}];

// Aggregate all responses
const responses = $input.all();
const aggregated = {
  timestamp: new Date().toISOString(),
  operations: responses.map(r => r.json),
  summary: {
    total_operations: responses.length,
    successful_operations: responses.filter(r => r.json.success).length,
    failed_operations: responses.filter(r => !r.json.success).length
  }
};

return [{
  json: aggregated
}];
